/**
 * Admin settings page for managing token gate rules.
 *
 * Rules are persisted as JSON in the `token_gating_rules` system setting.
 * Each rule specifies a token type, address/mint, minimum hold amount, and
 * which operations (deposits / withdrawals / all) are gated.
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useSystemSettings } from '../../hooks/useSystemSettings';
import type { TokenGateRule, TokenGateRuleType, TokenGateEnforcement } from '../../types/accreditation';

// =============================================================================
// Helpers
// =============================================================================

function generateId(): string {
  return `rule_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
}

function parseRules(raw: string | undefined): TokenGateRule[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function labelForType(t: TokenGateRuleType): string {
  switch (t) {
    case 'nft_collection': return 'NFT Collection';
    case 'fungible_token': return 'Fungible Token';
    case 'any_nft': return 'Any NFT';
  }
}

function labelForEnforcement(e: TokenGateEnforcement): string {
  switch (e) {
    case 'all': return 'All';
    case 'deposits': return 'Deposits';
    case 'withdrawals': return 'Withdrawals';
  }
}

// =============================================================================
// Form state
// =============================================================================

interface RuleFormState {
  name: string;
  ruleType: TokenGateRuleType;
  collectionAddress: string;
  mintAddress: string;
  minQuantity: string;
  minAmount: string;
  enforcement: TokenGateEnforcement;
}

const EMPTY_FORM: RuleFormState = {
  name: '',
  ruleType: 'nft_collection',
  collectionAddress: '',
  mintAddress: '',
  minQuantity: '',
  minAmount: '',
  enforcement: 'all',
};

function formFromRule(rule: TokenGateRule): RuleFormState {
  return {
    name: rule.name,
    ruleType: rule.ruleType,
    collectionAddress: rule.collectionAddress ?? '',
    mintAddress: rule.mintAddress ?? '',
    minQuantity: rule.minQuantity !== undefined ? String(rule.minQuantity) : '',
    minAmount: rule.minAmount ?? '',
    enforcement: rule.enforcement,
  };
}

function ruleFromForm(form: RuleFormState, id: string): TokenGateRule {
  return {
    id,
    name: form.name.trim(),
    ruleType: form.ruleType,
    collectionAddress: form.ruleType === 'nft_collection' ? form.collectionAddress.trim() || undefined : undefined,
    mintAddress: form.ruleType === 'fungible_token' ? form.mintAddress.trim() || undefined : undefined,
    minQuantity:
      form.ruleType !== 'fungible_token' && form.minQuantity
        ? parseInt(form.minQuantity, 10)
        : undefined,
    minAmount: form.ruleType === 'fungible_token' ? form.minAmount.trim() || undefined : undefined,
    enforcement: form.enforcement,
  };
}

// =============================================================================
// Props
// =============================================================================

export interface TokenGateSettingsProps {
  className?: string;
}

// =============================================================================
// Component
// =============================================================================

/**
 * Admin settings panel for token gate rules.
 *
 * Inputs: className optional CSS modifier.
 * Outputs: reads/writes `token_gating_rules` system setting as JSON.
 * Errors: displayed inline; save errors shown near the form.
 */
export function TokenGateSettings({ className = '' }: TokenGateSettingsProps) {
  const { fetchSettings, updateSettings, getValue, isLoading, error } = useSystemSettings();

  const [rules, setRules] = useState<TokenGateRule[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null); // null = new, string = existing id
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<RuleFormState>(EMPTY_FORM);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    fetchSettings();
  }, [fetchSettings]);

  // Sync rules from settings whenever settings load
  const rawRules = getValue('token_gating_rules');
  const parsedRules = useMemo(() => parseRules(rawRules), [rawRules]);
  useEffect(() => {
    setRules(parsedRules);
  }, [parsedRules]);

  const persistRules = useCallback(
    async (next: TokenGateRule[]) => {
      setIsSaving(true);
      setSaveError(null);
      try {
        await updateSettings([{ key: 'token_gating_rules', value: JSON.stringify(next) }]);
        setRules(next);
      } catch (err) {
        setSaveError(err instanceof Error ? err.message : 'Failed to save rules');
      } finally {
        setIsSaving(false);
      }
    },
    [updateSettings]
  );

  const handleAddClick = useCallback(() => {
    setEditingId(null);
    setForm(EMPTY_FORM);
    setSaveError(null);
    setShowForm(true);
  }, []);

  const handleEditClick = useCallback((rule: TokenGateRule) => {
    setEditingId(rule.id);
    setForm(formFromRule(rule));
    setSaveError(null);
    setShowForm(true);
  }, []);

  const handleDeleteClick = useCallback(
    (id: string) => {
      const next = rules.filter((r) => r.id !== id);
      persistRules(next);
    },
    [rules, persistRules]
  );

  const handleCancel = useCallback(() => {
    setShowForm(false);
    setSaveError(null);
  }, []);

  const handleSave = useCallback(async () => {
    if (!form.name.trim()) {
      setSaveError('Rule name is required.');
      return;
    }
    const id = editingId ?? generateId();
    const rule = ruleFromForm(form, id);
    const next = editingId
      ? rules.map((r) => (r.id === editingId ? rule : r))
      : [...rules, rule];
    await persistRules(next);
    if (!saveError) {
      setShowForm(false);
    }
  }, [form, editingId, rules, persistRules, saveError]);

  const setField = useCallback(<K extends keyof RuleFormState>(key: K, value: RuleFormState[K]) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  }, []);

  if (isLoading && rules.length === 0) {
    return (
      <div className={`cedros-admin-token-gate ${className} cedros-admin-token-gate--loading`}>
        <span className="cedros-admin-loading-indicator" />
        <span className="cedros-admin-loading-text">Loading token gate rules...</span>
      </div>
    );
  }

  if (error && rules.length === 0) {
    return (
      <div className={`cedros-admin-token-gate ${className} cedros-admin-token-gate--error`}>
        <p className="cedros-admin-error">{error.message}</p>
        <button type="button" className="cedros-button cedros-button-outline cedros-button-sm" onClick={fetchSettings}>
          Retry
        </button>
      </div>
    );
  }

  return (
    <div className={`cedros-admin-token-gate ${className}`}>
      <div className="cedros-admin-token-gate__header">
        <h2 className="cedros-admin-token-gate__title">Token Gate Rules</h2>
        <button
          type="button"
          className="cedros-button cedros-button-primary cedros-button-sm"
          onClick={handleAddClick}
          disabled={showForm}
        >
          Add Rule
        </button>
      </div>

      {showForm && (
        <RuleForm
          form={form}
          isNew={editingId === null}
          isSaving={isSaving}
          saveError={saveError}
          onFieldChange={setField}
          onSave={handleSave}
          onCancel={handleCancel}
        />
      )}

      {rules.length === 0 && !showForm ? (
        <div className="cedros-admin-empty-message">No token gate rules configured.</div>
      ) : (
        <div
          className="cedros-admin-list-table"
          role="table"
          aria-label="Token gate rules"
        >
          <div className="cedros-admin-list-thead" role="row">
            <div className="cedros-admin-list-th" role="columnheader">Name</div>
            <div className="cedros-admin-list-th" role="columnheader">Type</div>
            <div className="cedros-admin-list-th" role="columnheader">Address / Mint</div>
            <div className="cedros-admin-list-th" role="columnheader">Min Qty / Amount</div>
            <div className="cedros-admin-list-th" role="columnheader">Enforcement</div>
            <div className="cedros-admin-list-th" role="columnheader">Actions</div>
          </div>
          {rules.map((rule) => (
            <div key={rule.id} className="cedros-admin-list-row" role="row">
              <div className="cedros-admin-list-td" role="cell">{rule.name}</div>
              <div className="cedros-admin-list-td" role="cell">{labelForType(rule.ruleType)}</div>
              <div className="cedros-admin-list-td cedros-admin-list-td-mono" role="cell">
                {rule.collectionAddress || rule.mintAddress || '—'}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {rule.minQuantity !== undefined ? rule.minQuantity : (rule.minAmount ?? '—')}
              </div>
              <div className="cedros-admin-list-td" role="cell">
                {labelForEnforcement(rule.enforcement)}
              </div>
              <div className="cedros-admin-list-td cedros-admin-list-td-actions" role="cell">
                <button
                  type="button"
                  className="cedros-button cedros-button-outline cedros-button-sm"
                  onClick={() => handleEditClick(rule)}
                  disabled={showForm}
                >
                  Edit
                </button>
                <button
                  type="button"
                  className="cedros-button cedros-button-danger cedros-button-sm"
                  onClick={() => handleDeleteClick(rule.id)}
                  disabled={isSaving || showForm}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// =============================================================================
// RuleForm sub-component
// =============================================================================

interface RuleFormProps {
  form: RuleFormState;
  isNew: boolean;
  isSaving: boolean;
  saveError: string | null;
  onFieldChange: <K extends keyof RuleFormState>(key: K, value: RuleFormState[K]) => void;
  onSave: () => void;
  onCancel: () => void;
}

function RuleForm({ form, isNew, isSaving, saveError, onFieldChange, onSave, onCancel }: RuleFormProps) {
  const showCollection = form.ruleType === 'nft_collection';
  const showMint = form.ruleType === 'fungible_token';
  const showMinQty = form.ruleType !== 'fungible_token';
  const showMinAmount = form.ruleType === 'fungible_token';

  return (
    <div className="cedros-admin-token-gate__form" role="region" aria-label={isNew ? 'Add rule' : 'Edit rule'}>
      <h3 className="cedros-admin-token-gate__form-title">{isNew ? 'Add Rule' : 'Edit Rule'}</h3>

      <div className="cedros-admin-form-row">
        <label className="cedros-admin-form-label" htmlFor="tg-name">Name</label>
        <input
          id="tg-name"
          type="text"
          className="cedros-admin-form-input"
          value={form.name}
          onChange={(e) => onFieldChange('name', e.target.value)}
          placeholder="e.g. Whale Gate"
        />
      </div>

      <div className="cedros-admin-form-row">
        <label className="cedros-admin-form-label" htmlFor="tg-type">Type</label>
        <select
          id="tg-type"
          className="cedros-admin-form-select"
          value={form.ruleType}
          onChange={(e) => onFieldChange('ruleType', e.target.value as TokenGateRuleType)}
        >
          <option value="nft_collection">NFT Collection</option>
          <option value="fungible_token">Fungible Token</option>
          <option value="any_nft">Any NFT</option>
        </select>
      </div>

      {showCollection && (
        <div className="cedros-admin-form-row">
          <label className="cedros-admin-form-label" htmlFor="tg-collection">Collection Address</label>
          <input
            id="tg-collection"
            type="text"
            className="cedros-admin-form-input cedros-admin-form-input--mono"
            value={form.collectionAddress}
            onChange={(e) => onFieldChange('collectionAddress', e.target.value)}
            placeholder="Solana collection mint address"
          />
        </div>
      )}

      {showMint && (
        <div className="cedros-admin-form-row">
          <label className="cedros-admin-form-label" htmlFor="tg-mint">Mint Address</label>
          <input
            id="tg-mint"
            type="text"
            className="cedros-admin-form-input cedros-admin-form-input--mono"
            value={form.mintAddress}
            onChange={(e) => onFieldChange('mintAddress', e.target.value)}
            placeholder="SPL token mint address"
          />
        </div>
      )}

      {showMinQty && (
        <div className="cedros-admin-form-row">
          <label className="cedros-admin-form-label" htmlFor="tg-minqty">Min Quantity</label>
          <input
            id="tg-minqty"
            type="number"
            min="1"
            className="cedros-admin-form-input"
            value={form.minQuantity}
            onChange={(e) => onFieldChange('minQuantity', e.target.value)}
            placeholder="1"
          />
        </div>
      )}

      {showMinAmount && (
        <div className="cedros-admin-form-row">
          <label className="cedros-admin-form-label" htmlFor="tg-minamount">Min Amount</label>
          <input
            id="tg-minamount"
            type="text"
            className="cedros-admin-form-input"
            value={form.minAmount}
            onChange={(e) => onFieldChange('minAmount', e.target.value)}
            placeholder="e.g. 1000000 (raw units)"
          />
        </div>
      )}

      <div className="cedros-admin-form-row">
        <label className="cedros-admin-form-label" htmlFor="tg-enforcement">Enforcement</label>
        <select
          id="tg-enforcement"
          className="cedros-admin-form-select"
          value={form.enforcement}
          onChange={(e) => onFieldChange('enforcement', e.target.value as TokenGateEnforcement)}
        >
          <option value="all">All</option>
          <option value="deposits">Deposits</option>
          <option value="withdrawals">Withdrawals</option>
        </select>
      </div>

      {saveError && <p className="cedros-admin-error">{saveError}</p>}

      <div className="cedros-admin-token-gate__form-actions">
        <button
          type="button"
          className="cedros-button cedros-button-primary cedros-button-sm"
          onClick={onSave}
          disabled={isSaving}
          aria-busy={isSaving}
        >
          {isSaving ? 'Saving...' : 'Save Rule'}
        </button>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onCancel}
          disabled={isSaving}
        >
          Cancel
        </button>
      </div>
    </div>
  );
}
